package com.meterflow.budgets;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.Authentication;import java.math.*;import java.util.*;
@RestController @RequestMapping("/api/budgets")public class BudgetController{private final BudgetService s;public BudgetController(BudgetService s){this.s=s;}public record Input(@NotBlank String customerId,@NotBlank String period,@NotNull @DecimalMin("0.01") BigDecimal amount,@NotBlank String currency){}
@PostMapping public UsageBudget set(@Valid @RequestBody Input i,Authentication a){guard(i.customerId(),a);return s.set(i.customerId(),i.period(),i.amount(),i.currency());}@GetMapping("/evaluate")public Map<String,Object> evaluate(@RequestParam String customerId,@RequestParam String period,Authentication a){guard(customerId,a);return s.evaluate(customerId,period);}private void guard(String c,Authentication a){if(a.getAuthorities().stream().noneMatch(x->x.getAuthority().equals("ROLE_ADMIN"))&&!a.getName().equals(c))throw new org.springframework.security.access.AccessDeniedException("Customer access denied");}}
